<script setup>
import { onMounted, ref } from 'vue'
import ListView from '../shared/components/ListView.vue'

const props = defineProps({ token: { type: String, required: true } })
const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref('')
const items = ref([]); const selected = ref(null); const adminNote = ref('')
const pagination = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 })
const feedbackItems = ref([]); const feedbackPagination = ref({ page: 1, pageSize: 10, totalItems: 0, totalPages: 1 })

async function request(url, options = {}) { const response = await fetch(url, { ...options, headers: { Authorization: `Bearer ${props.token}`, ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'No se pudo completar la operación.'); return data }
async function load(page = pagination.value.page) { loading.value = true; error.value = ''; try { const [data, feedback] = await Promise.all([request(`/api/app/reviews/responses?page=${page}&pageSize=10`), request(`/api/app/reviews/feedback?page=${feedbackPagination.value.page}&pageSize=10`)]); items.value = data.items || []; pagination.value = data.pagination || pagination.value; feedbackItems.value = feedback.items || []; feedbackPagination.value = feedback.pagination || feedbackPagination.value } catch (loadError) { error.value = loadError.message } finally { loading.value = false } }
function open(item) { selected.value = item; adminNote.value = '' }
function close() { selected.value = null; adminNote.value = '' }
async function review(action) { if (!selected.value) return; saving.value = true; error.value = ''; try { const data = await request(`/api/app/reviews/responses/${selected.value.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action, adminNote: adminNote.value }) }); notice.value = action === 'approve' ? (data.queued ? 'Respuesta aprobada; el correo quedó en la cola de envío.' : `Respuesta aprobada. ${data.reason || 'Quedó pendiente de envío.'}`) : 'Respuesta devuelta al experto.'; close(); await load() } catch (reviewError) { error.value = reviewError.message } finally { saving.value = false } }
function label(value) { return { importacion: 'Importación', exportacion: 'Exportación', agente_carga: 'Agente de carga' }[value] || value }
onMounted(load)
</script>

<template>
  <section class="module-view review-view">
    <div class="module-heading"><div><p class="eyebrow">Control de calidad</p><h1>Revisión de respuestas</h1><p>Valida la orientación del experto antes de enviarla al cliente.</p></div><button type="button" class="secondary-button compact" @click="load">↻ Actualizar</button></div>
    <p v-if="notice" class="security-notice">{{ notice }}</p><p v-if="error" class="request-error">{{ error }}</p>
    <ListView title="Respuestas pendientes" description="Las respuestas aprobadas se envían al correo registrado del cliente." :count="pagination.totalItems" :page="pagination.page" :total-pages="pagination.totalPages" :loading="loading" :empty="!items.length && !loading" empty-text="No hay respuestas pendientes de revisión." @previous="load(pagination.page - 1)" @next="load(pagination.page + 1)"><template #columns><th>Solicitud</th><th>Cliente</th><th>Servicio</th><th>Experto</th><th>Versión</th><th>Creada</th><th>Acción</th></template><template #rows><tr v-for="item in items" :key="item.id"><td><strong class="request-id">{{ item.reference }}</strong></td><td><strong>{{ item.clientName }}</strong><br /><span class="muted-cell">{{ item.clientEmail || 'Sin correo' }}</span></td><td>{{ item.consultationType || label(item.serviceType) }}</td><td>{{ item.expertName }}</td><td><span class="count-badge">v{{ item.version }}</span></td><td>{{ new Date(item.createdAt).toLocaleDateString('es-CO') }}</td><td><button type="button" class="secondary-button compact" @click="open(item)">Revisar</button></td></tr></template></ListView>
    <ListView title="Feedback recibido" description="Las calificaciones bajas quedan marcadas para seguimiento administrativo." :count="feedbackPagination.totalItems" :page="feedbackPagination.page" :total-pages="feedbackPagination.totalPages" :loading="loading" :empty="!feedbackItems.length && !loading" empty-text="Aún no hay feedback recibido."><template #columns><th>Solicitud</th><th>Cliente</th><th>Consulta</th><th>Experto</th><th>Calificación</th><th>Comentario</th><th>Estado</th></template><template #rows><tr v-for="item in feedbackItems" :key="item.id"><td><strong class="request-id">{{ item.reference }}</strong></td><td>{{ item.clientName }}</td><td>{{ item.consultationType || '—' }}</td><td>{{ item.expertName || '—' }}</td><td><span :class="['feedback-rating', { low: item.rating <= 3 }]">{{ item.rating }} / 5</span></td><td class="feedback-comment">{{ item.comment || 'Sin comentario' }}</td><td><span :class="['security-status', { inactive: item.status === 'escalated' }]">{{ item.status === 'escalated' ? 'Requiere atención' : 'Recibido' }}</span></td></tr></template></ListView>
    <div v-if="selected" class="review-backdrop" @click.self="close"><section class="review-panel"><div class="panel-heading"><div><p class="eyebrow">{{ selected.reference }}</p><h2>Respuesta del experto</h2><p>{{ selected.expertName }} · versión {{ selected.version }}</p></div><button type="button" class="secondary-button compact" @click="close">Cerrar</button></div><div class="review-meta"><span><strong>Cliente:</strong> {{ selected.clientName }}</span><span><strong>Servicio:</strong> {{ selected.consultationType || label(selected.serviceType) }}</span></div><article class="response-copy">{{ selected.body }}</article><label>Nota para el cliente (opcional)<textarea v-model="adminNote" rows="5" maxlength="5000" placeholder="Agrega una aclaración o indicación adicional..."></textarea></label><div class="review-actions"><button type="button" class="danger-link" :disabled="saving" @click="review('reject')">Devolver al experto</button><button type="button" class="primary-button" :disabled="saving" @click="review('approve')">{{ saving ? 'Procesando…' : 'Aprobar y enviar' }} <span>→</span></button></div></section></div>
  </section>
</template>

<style scoped>
.review-view .module-heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:24px}.review-view .module-heading h1{margin:0 0 8px;color:#142c43;font-size:28px;letter-spacing:-.045em}.review-view .module-heading p:last-child{margin:0;color:#7d8999;font-size:13px}.review-backdrop{position:fixed;inset:0;z-index:30;display:flex;justify-content:flex-end;background:rgba(9,30,48,.28)}.review-panel{width:min(620px,100%);height:100%;overflow:auto;display:grid;align-content:start;gap:18px;padding:36px;background:#fff;box-shadow:-14px 0 35px rgba(16,39,59,.14)}.review-panel h2{margin:0 0 5px;color:#223b53;font-size:20px}.review-panel .panel-heading p:last-child{margin:0;color:#98a2b3;font-size:10px}.review-meta{display:grid;gap:8px;padding:14px;border:1px solid #dce7f0;border-radius:8px;background:#f6fafc;color:#526174;font-size:11px}.response-copy{padding:18px;border:1px solid #e5eaf0;border-radius:8px;color:#344b60;font-size:13px;line-height:1.7;white-space:pre-wrap}.review-panel label{display:grid;gap:8px;color:#526174;font-size:10px;font-weight:800}.review-panel textarea{width:100%;padding:12px;border:1px solid #d8e0ea;border-radius:7px;outline:0;color:#344b60;background:#fff;font:inherit;font-size:12px;line-height:1.5;resize:vertical}.review-actions{display:flex;justify-content:flex-end;gap:8px;align-items:center}.review-actions .danger-link{min-height:36px}.review-actions .primary-button{min-height:36px;padding:0 13px;border:0;border-radius:7px;color:#fff;background:#0e4567;font-size:11px;font-weight:800;cursor:pointer}.feedback-rating{display:inline-flex;padding:4px 7px;border-radius:5px;color:#348267;background:#e9f7f0;font-size:10px;font-weight:800}.feedback-rating.low{color:#b54747;background:#fff0f1}.feedback-comment{max-width:260px;white-space:normal!important;line-height:1.4}@media(max-width:720px){.review-view .module-heading{display:block}.review-view .module-heading .secondary-button{margin-top:16px}.review-panel{padding:24px 18px}}
</style>
